// Group contacts by hotel_id to process them together
const contacts = $input.all().map(i => i.json);
if (contacts.length === 0) return [];

const hotelGroups = {};
for (const contact of contacts) {
  const hId = contact.hotel_id;
  if (!hotelGroups[hId]) {
    hotelGroups[hId] = [];
  }
  hotelGroups[hId].push(contact);
}

return Object.keys(hotelGroups).slice(0, 5).map(hId => ({
  json: {
    hotel_id: hId,
    emails_found: hotelGroups[hId]
  }
}));

// Prepare Groq Prompt
const hotel = $('Get Hotel Details').first().json || {};
const groupData = $('Group by Hotel').item.json || {};
const emails = groupData.emails_found || [];

const inputData = {
  hotel: {
    name: hotel.hotel_name || '',
    town: hotel.town || '',
    website: hotel.website || ''
  },
  emails_found: emails.map(e => ({
    email: e.email,
    source_url: e.source_url,
    context: e.source_text || ''
  }))
};

const systemPrompt = `Eres un clasificador de contactos empresariales para candidaturas laborales.
Solo puedes seleccionar direcciones que aparezcan literalmente en emails_found.
No inventes, completes ni adivines correos.
Prioriza JOBS y HR, después MANAGEMENT, GENERAL y finalmente RECEPTION/RESERVATION.
Un correo GENERAL requiere manual_review=true.
Marca accommodation o meals como YES/NO únicamente con evidencia explícita.
Devuelve exclusivamente JSON válido conforme al esquema solicitado.`;

const schemaInfo = `
Esquema de salida requerido:
{
  "is_target_establishment": true,
  "language_region": "DE",
  "has_food_operation": true,
  "best_email": "jobs@example.ch",
  "email_type": "JOBS",
  "contact_name": null,
  "contact_role": null,
  "accommodation": "UNKNOWN",
  "meals": "UNKNOWN",
  "manual_review": false,
  "reason": "Public jobs address found on career page",
  "confidence": 0.98
}`;

return [{
  json: {
    hotel_id: hotel.hotel_id,
    prompt: JSON.stringify(inputData, null, 2) + schemaInfo,
    system: systemPrompt,
    emails: emails
  }
}];

// Validate Groq Output
const apiResponse = $input.first().json;
const promptData = $('Prepare Groq Prompt').item.json;
const emails = promptData.emails;

let parsed;
try {
  const content = apiResponse.choices[0].message.content;
  parsed = JSON.parse(content);
} catch (e) {
  throw new Error('Groq returned invalid JSON');
}

// Rule 1: best_email must exist in emails_found
const bestEmail = parsed.best_email;
if (bestEmail && !emails.find(e => e.email.toLowerCase() === bestEmail.toLowerCase())) {
  parsed.manual_review = true;
  parsed.reason = 'Groq hallucinated email: ' + bestEmail;
  parsed.best_email = null;
}

// Rule 2: confidence
const conf = parsed.confidence || 0;
if (conf < 0 || conf > 1) parsed.confidence = 0.5;

// Rule 3: Classification logic
let finalStatus = 'NEEDS_REVIEW';
if (parsed.manual_review) {
  finalStatus = 'NEEDS_REVIEW';
} else if (['GENERAL', 'RECEPTION', 'RESERVATION', 'UNKNOWN'].includes(parsed.email_type)) {
  finalStatus = 'NEEDS_REVIEW';
} else if (['HR', 'JOBS'].includes(parsed.email_type) && conf >= 0.85) {
  finalStatus = 'READY_TO_SEND';
}

// Rule 4: Reject non-targets
if (parsed.is_target_establishment === false) {
  finalStatus = 'REJECTED';
}

// Update contacts list with decision
const results = emails.map(e => {
  const isSelected = e.email.toLowerCase() === (parsed.best_email || '').toLowerCase();
  return {
    json: {
      contact_id: e.contact_id,
      hotel_id: e.hotel_id,
      email: e.email,
      email_type: isSelected ? parsed.email_type : e.email_type,
      contact_name: isSelected ? parsed.contact_name : null,
      contact_role: isSelected ? parsed.contact_role : null,
      confidence: isSelected ? parsed.confidence : e.confidence,
      preferred: isSelected,
      review_status: isSelected ? finalStatus : 'REJECTED',
      groq_reason: isSelected ? parsed.reason : 'Not selected'
    }
  };
});

// Add hotel update data
const hotelUpdate = {
  hotel_id: promptData.hotel_id,
  language_region: parsed.language_region,
  accommodation: parsed.accommodation,
  meals: parsed.meals,
  manual_review: finalStatus === 'NEEDS_REVIEW' ? 'TRUE' : 'FALSE',
  status: finalStatus === 'READY_TO_SEND' ? 'READY_TO_SEND' : 
         (finalStatus === 'NEEDS_REVIEW' ? 'NEEDS_REVIEW' : 'REJECTED')
};

return [{ json: { contacts: results.map(r => r.json), hotel: hotelUpdate } }];
